import {
  reactExtension,
  useAuthenticatedAccountCustomer,
  useAuthenticatedAccountPurchasingCompany,
} from '@shopify/ui-extensions-react/customer-account';
import {Banner, BlockStack, Text} from '@shopify/ui-extensions/customer-account';

export default reactExtension(
  'customer-account.order-status.block.render',
  () =&gt; &lt;Extension /&gt;,
);

function Extension() {
  const customer = useAuthenticatedAccountCustomer();
  const company = useAuthenticatedAccountPurchasingCompany();
  if (!customer) return null;
  if (!company) return &lt;Text&gt;Customer: {customer.id}&lt;/Text&gt;;
  return (
    &lt;Banner status="info"&gt;
      &lt;BlockStack&gt;
        &lt;Text emphasis="bold"&gt;{company.company.id}&lt;/Text&gt;
        {company.location && &lt;Text&gt;Location: {company.location.id}&lt;/Text&gt;}
      &lt;/BlockStack&gt;
    &lt;/Banner&gt;
  );
}

import {extension, Banner, BlockStack, Text} from '@shopify/ui-extensions/customer-account';

export default extension(
  'customer-account.order-status.block.render',
  (root, api) =&gt; {
    const customer = api.authenticatedAccount.customer.current;
    const company = api.authenticatedAccount.purchasingCompany.current;
    if (!customer) return;
    if (!company) {
      root.appendChild(root.createComponent(Text, {}, `Customer: ${customer.id}`));
      return;
    }
    const banner = root.createComponent(Banner, {status: 'info'});
    const stack = root.createComponent(BlockStack, {});
    stack.appendChild(root.createComponent(Text, {emphasis: 'bold'}, company.company.id));
    if (company.location) {
      stack.appendChild(root.createComponent(Text, {}, `Location: ${company.location.id}`));
    }
    banner.appendChild(stack);
    root.appendChild(banner);
  },
);

import {
  reactExtension,
  useAuthenticatedAccountCustomer,
  useCustomer,
  useI18n,
} from '@shopify/ui-extensions-react/customer-account';
import {Banner, Link} from '@shopify/ui-extensions/customer-account';

export default reactExtension(
  'customer-account.order-status.block.render',
  () =&gt; &lt;Extension /&gt;,
);

function Extension() {
  const i18n = useI18n();
  const authenticatedCustomer = useAuthenticatedAccountCustomer();
  const orderStatusCustomer = useCustomer();

  if (
    authenticatedCustomer?.id &&
    orderStatusCustomer?.id?.endsWith(authenticatedCustomer?.id)
  ) {
    return (
      &lt;Banner&gt;
        &lt;Link to={'extension:manageLoyaltyPoints/'}&gt;
          {i18n.translate('manageLoyaltyPoints')}
        &lt;/Link&gt;
      &lt;/Banner&gt;
    );
  }
  return null;
}

import {extension, Banner, Link} from '@shopify/ui-extensions/customer-account';

export default extension(
  'customer-account.order-status.block.render',
  (root, api) =&gt; {
    const authenticatedCustomer = api.authenticatedAccount.customer.current;
    const orderStatusCustomer = api.buyerIdentity?.customer.current;

    if (
      authenticatedCustomer?.id &&
      orderStatusCustomer?.id?.endsWith(authenticatedCustomer?.id)
    ) {
      const banner = root.createComponent(Banner, {});
