        }
      })
      .catch(console.error);
  },
);

import React, {useEffect, useState} from 'react';
import {reactExtension} from '@shopify/ui-extensions-react/customer-account';
import {BlockStack, Text} from '@shopify/ui-extensions/customer-account';

const API_VERSION = '2025-07';

export default reactExtension(
  'customer-account.order-status.block.render',
  () =&gt; &lt;Extension /&gt;,
);

function Extension() {
  const [orderCount, setOrderCount] = useState&lt;number | null&gt;(null);

  useEffect(() =&gt; {
    fetch(`shopify://customer-account/api/${API_VERSION}/graphql.json`, {
      method: 'POST',
      headers: {'Content-Type': 'application/json'},
      body: JSON.stringify({
        query: `query { customer { orders(first: 100) { nodes { id } } } }`,
      }),
    })
      .then((res) =&gt; res.json())
      .then(({data}) =&gt; {
        if (!data.customer) return;
        setOrderCount(data.customer.orders.nodes.length);
      })
      .catch(console.error);
  }, []);

  if (orderCount === null) return null;
  return (
    &lt;BlockStack&gt;
      &lt;Text&gt;You have placed {orderCount} order{orderCount !== 1 ? 's' : ''} with us.&lt;/Text&gt;
    &lt;/BlockStack&gt;
  );
}

import {extension, BlockStack, Text} from '@shopify/ui-extensions/customer-account';

const API_VERSION = '2025-07';

export default extension(
  'customer-account.order-status.block.render',
  (root, api) =&gt; {
    fetch(`shopify://customer-account/api/${API_VERSION}/graphql.json`, {
      method: 'POST',
      headers: {'Content-Type': 'application/json'},
      body: JSON.stringify({
        query: `query { customer { orders(first: 100) { nodes { id } } } }`,
      }),
    })
      .then((res) =&gt; res.json())
      .then(({data}) =&gt; {
        if (!data.customer) return;
        const count = data.customer.orders.nodes.length;
        const stack = root.createComponent(BlockStack, {});
        stack.appendChild(
          root.createComponent(Text, {}, `You have placed ${count} order${count !== 1 ? 's' : ''} with us.`),
        );
        root.appendChild(stack);
      })
      .catch(console.error);
  },
);

import React, {useEffect, useState} from 'react';
import {reactExtension} from '@shopify/ui-extensions-react/customer-account';
import {BlockStack, Text} from '@shopify/ui-extensions/customer-account';

const API_VERSION = '2025-07';

export default reactExtension(
  'customer-account.order-status.block.render',
  () =&gt; &lt;Extension /&gt;,
);

function Extension() {
  const [addresses, setAddresses] = useState&lt;{city?: string; zoneCode?: string; territoryCode?: string}[]&gt;([]);

  useEffect(() =&gt; {
    fetch(`shopify://customer-account/api/${API_VERSION}/graphql.json`, {
      method: 'POST',
      headers: {'Content-Type': 'application/json'},
      body: JSON.stringify({
        query: `query {
          customer {
            addresses(first: 3) {
              nodes { city zoneCode territoryCode }
            }
          }
        }`,
      }),
    })
      .then((res) =&gt; res.json())
      .then(({data}) =&gt; {
        if (!data.customer) return;
        setAddresses(data.customer.addresses.nodes);
      })
      .catch(console.error);
  }, []);

  if (addresses.length === 0) return null;
  return (
    &lt;BlockStack&gt;
      &lt;Text emphasis="bold"&gt;Saved addresses&lt;/Text&gt;
      {addresses.map((addr, i) =&gt; (
        &lt;Text key={i}&gt;
          {[addr.city, addr.zoneCode, addr.territoryCode].filter(Boolean).join(', ')}
        &lt;/Text&gt;
      ))}
    &lt;/BlockStack&gt;
  );
}

import {extension, BlockStack, Text} from '@shopify/ui-extensions/customer-account';

const API_VERSION = '2025-07';

export default extension(
  'customer-account.order-status.block.render',
  (root, api) =&gt; {
    fetch(`shopify://customer-account/api/${API_VERSION}/graphql.json`, {
      method: 'POST',
      headers: {'Content-Type': 'application/json'},
      body: JSON.stringify({
        query: `query {
          customer {
            addresses(first: 3) {
              nodes { city zoneCode territoryCode }
            }
          }
        }`,
      }),
    })
      .then((res) =&gt; res.json())
      .then(({data}) =&gt; {
        if (!data.customer) return;
        const addrs = data.customer.addresses.nodes;
        if (addrs.length === 0) return;
        const stack = root.createComponent(BlockStack, {});
        stack.appendChild(root.createComponent(Text, {emphasis: 'bold'}, 'Saved addresses'));
        for (const addr of addrs) {
          stack.appendChild(
            root.createComponent(Text, {}, [addr.city, addr.zoneCode, addr.territoryCode].filter(Boolean).join(', ')),
          );
        }
        root.appendChild(stack);
      })
      .catch(console.error);
  },
);

import {
  reactExtension,
  useCustomerPrivacy,
} from '@shopify/ui-extensions-react/customer-account';
import {BlockStack, Text} from '@shopify/ui-extensions/customer-account';

export default reactExtension(
  'customer-account.order-status.block.render',
  () =&gt; &lt;Extension /&gt;,
);

function consentLabel(value?: boolean) {
  if (value === true) return 'Allowed';
  if (value === false) return 'Not allowed';
  return 'No decision';
}

function Extension() {
  const privacy = useCustomerPrivacy();
  return (
    &lt;BlockStack&gt;
      &lt;Text emphasis="bold"&gt;Privacy settings&lt;/Text&gt;
      &lt;Text&gt;Analytics: {consentLabel(privacy.visitorConsent.analytics)}&lt;/Text&gt;
      &lt;Text&gt;Marketing: {consentLabel(privacy.visitorConsent.marketing)}&lt;/Text&gt;
    &lt;/BlockStack&gt;
  );
}

import {extension, BlockStack, Text} from '@shopify/ui-extensions/customer-account';

function consentLabel(value?: boolean) {
