  const lines = useCartLines();

  return (
    &lt;BlockStack&gt;
      &lt;Text emphasis="bold"&gt;Order items ({lines.length})&lt;/Text&gt;
      {lines.map((line) =&gt; (
        &lt;Text key={line.id}&gt;
          {line.merchandise.title} × {line.quantity} —{' '}
