          {line.lineComponents.map((component) =&gt; (
            &lt;Text key={component.id} appearance="subdued"&gt;
              ↳ {component.merchandise.title} ×{' '}
              {component.quantity}
            &lt;/Text&gt;
          ))}
        &lt;/BlockStack&gt;
      ))}
    &lt;/BlockStack&gt;
