import {
  reactExtension,
  useDiscountAllocations,
  useI18n,
} from '@shopify/ui-extensions-react/customer-account';
import {
  BlockStack,
  Text,
} from '@shopify/ui-extensions/customer-account';

export default reactExtension(
  'customer-account.order-status.block.render',
  () =&gt; &lt;Extension /&gt;,
);

function Extension() {
  const allocations = useDiscountAllocations();
  const i18n = useI18n();

  if (allocations.length === 0) {
    return null;
  }

  const totalSavings = allocations.reduce(
    (sum, alloc) =&gt; sum + alloc.discountedAmount.amount,
    0,
  );

  const currency = allocations[0].discountedAmount.currencyCode;

  return (
    &lt;BlockStack&gt;
      &lt;Text emphasis="bold"&gt;
        You saved {i18n.formatCurrency(totalSavings, {currency})}
      &lt;/Text&gt;
      {allocations.map((alloc, index) =&gt; (
        &lt;Text key={index} appearance="subdued"&gt;
          {alloc.type === 'code'
            ? `Code "${alloc.code}"`
            : alloc.title}{' '}
          — {i18n.formatCurrency(
            alloc.discountedAmount.amount,
            {currency},
          )}
        &lt;/Text&gt;
      ))}
    &lt;/BlockStack&gt;
  );
}

import {
  extension,
  BlockStack,
  Text,
} from '@shopify/ui-extensions/customer-account';

export default extension(
  'customer-account.order-status.block.render',
  (root, api) =&gt; {
    const allocations = api.discountAllocations.current;

    if (allocations.length === 0) return;

    const totalSavings = allocations.reduce(
      (sum, alloc) =&gt; sum + alloc.discountedAmount.amount,
      0,
    );
    const currency = allocations[0].discountedAmount.currencyCode;

    const stack = root.createComponent(BlockStack, {});
    stack.appendChild(
      root.createComponent(
        Text,
        {emphasis: 'bold'},
        `You saved ${api.i18n.formatCurrency(totalSavings, {currency})}`,
      ),
    );

    for (const alloc of allocations) {
