import {
  BlockStack,
  Button,
  InlineStack,
  Link,
  Modal,
  reactExtension,
  TextField,
  Text,
} from '@shopify/ui-extensions-react/customer-account';

// 1. Choose an extension target
export default reactExtension(
  'customer-account.profile.announcement.render',
  () =&gt; &lt;Extension /&gt;,
);

function Extension() {
  // 2. Render a UI
  return (
    &lt;InlineStack&gt;
      &lt;Text&gt;Check our latest offers&lt;/Text&gt;
      &lt;Link
        overlay={
          &lt;Modal
            title="Tell us about your shopping experience"
            padding
          &gt;
            &lt;BlockStack&gt;
              &lt;Text&gt;
                We'd love to hear about your
                shopping experience
              &lt;/Text&gt;
              &lt;TextField
                multiline={4}
                label="How can we make your shopping experience better?"
              &gt;&lt;/TextField&gt;
              &lt;Button&gt;Submit&lt;/Button&gt;
            &lt;/BlockStack&gt;
          &lt;/Modal&gt;
        }
      &gt;
        Fill out the survey
      &lt;/Link&gt;
    &lt;/InlineStack&gt;
  );
}

import {
  BlockStack,
  Button,
  InlineStack,
  Link,
  Modal,
  TextField,
  Text,
  extension,
} from '@shopify/ui-extensions/customer-account';

export default extension(
  'customer-account.profile.announcement.render',
  (root) =&gt; {
    const modalFragment = root.createFragment();
    modalFragment.appendChild(
      root.createComponent(
        Modal,
        {
          title:
            'Tell us about your shopping experience',
          padding: true,
        },
        [
          root.createComponent(
            BlockStack,
            undefined,
            [
              root.createComponent(
                Text,
                undefined,
                "We'd love to hear about your shopping experience",
              ),
              root.createComponent(TextField, {
                multiline: 4,
                label:
                  'How can we make your shopping experience better?',
              }),
              root.createComponent(
                Button,
                undefined,
                'Submit',
              ),
            ],
          ),
        ],
      ),
    );

    root.appendChild(
      root.createComponent(
        InlineStack,
        undefined,
        [
          root.createComponent(
            Text,
            undefined,
            'Check our latest offers',
          ),
          root.createComponent(
            Link,
            {
              overlay: modalFragment,
            },
            'Fill out the survey',
          ),
        ],
      ),
    );
  },
);

