      },
      [pressable, disclosureView],
    );

    const inlineLayout = root.createComponent(
      InlineLayout,
      {
        blockAlignment: 'baseline',
        spacing: 'base',
        columns: ['auto', 'fill', 'auto'],
        padding: 'base',
