}) =&gt; (
  &lt;View
    minBlockSize={64}
    cornerRadius="large"
    maxInlineSize={64}
    minInlineSize={64}
    border="base"
  &gt;
    {source ? (
      &lt;Image
        fit="cover"
        aspectRatio={1}
        source={source}
        cornerRadius="large"
      /&gt;
    ) : (
